# RQ-B4 시험용 「가짜」 등기부 PDF 만들기(2026-11-04). 이름·주소·번호는 모두 지어낸 값이며 실제 사람·부동산과 무관하다.
# 실행: python -I tests/fixtures/make-fake-registry.py  → tests/fixtures/fake-registry.pdf
# 정답(대조용): 말소 안 된 근저당 1건 채권최고액 24,000만 원 / 말소된 근저당 1건(12,000만) / 가압류 1건 청구금액 3,000만 / 소유자 홍길동(→ 홍○○)
import os
from fpdf import FPDF

here = os.path.dirname(os.path.abspath(__file__))
pdf = FPDF()
pdf.add_font("malgun", "", r"C:\Windows\Fonts\malgun.ttf")
pdf.set_font("malgun", size=10)
pdf.add_page()

def line(text, size=10, h=6):
    pdf.set_font("malgun", size=size)
    pdf.multi_cell(0, h, text, new_x="LMARGIN", new_y="NEXT")

line("※ 시험용 가짜 문서 — 실제 등기부가 아닙니다(이름·주소는 지어낸 값)", 9)
line("등기사항전부증명서(말소사항 포함) - 집합건물", 15, 9)
line("[집합건물] 경기도 고양시 일산동구 시험동 9999 시험아파트 제101동 제1001호")
line("열람일시 : 2026년11월04일 21시10분")
pdf.ln(3)
line("【 표 제 부 】 (1동의 건물의 표시)", 12, 8)
line("철근콘크리트구조 20층 공동주택(아파트) / 전유부분 84.97㎡")
pdf.ln(3)
line("【 갑 구 】 (소유권에 관한 사항)", 12, 8)
rows_a = [
    ("1", "소유권보존", "2015년3월2일 제10001호", "", "소유자 주식회사시험건설"),
    ("2", "소유권이전", "2020년3월15일 제20456호", "2020년2월1일 매매", "소유자 홍길동 800101-******* 경기도 고양시 시험로 1  거래가액 금450,000,000원"),
    ("3", "가압류", "2026년6월10일 제35210호", "2026년6월8일 의정부지방법원 고양지원의 가압류결정(2026카단1234)", "청구금액 금30,000,000원  채권자 김채권 750505-*******"),
]
for r in rows_a:
    line(f"순위번호 {r[0]} | 등기목적 {r[1]} | 접수 {r[2]} | 등기원인 {r[3]} | 권리자 및 기타사항 {r[4]}", 9, 5)
    pdf.ln(1)
pdf.ln(3)
line("【 을 구 】 (소유권 이외의 권리에 관한 사항)", 12, 8)
rows_b = [
    ("1", "근저당권설정", "2020년3월15일 제20457호", "2020년3월15일 설정계약", "채권최고액 금240,000,000원  채무자 홍길동  근저당권자 주식회사국민시험은행"),
    ("2", "근저당권설정", "2023년8월1일 제31002호", "2023년8월1일 설정계약", "채권최고액 금120,000,000원  채무자 홍길동  근저당권자 시험캐피탈주식회사"),
    ("3", "2번근저당권설정등기말소", "2025년1월5일 제1203호", "2025년1월5일 해지", ""),
]
for r in rows_b:
    line(f"순위번호 {r[0]} | 등기목적 {r[1]} | 접수 {r[2]} | 등기원인 {r[3]} | 권리자 및 기타사항 {r[4]}", 9, 5)
    pdf.ln(1)
pdf.ln(4)
line("-- 이 하 여 백 --", 10)
pdf.output(os.path.join(here, "fake-registry.pdf"))
print("ok")
